// V3.1 Analyst Workspace: presentation utilities and components. The
// capability fixture is generated by the backend (tests/fixtures), so the UI
// is tested against server metadata, not a second hand-written catalog.
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mkdtempSync, writeFileSync, rmSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { createRequire } from 'node:module';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { buildSync } from 'esbuild';
import { coverageSummary, missionCards, visibleMissionId, missionMetrics, buildQuestion, suggestionChips, capabilityGroups, unsupportedItems,
  groupDifference, missionTabs, orderChartsByMission, kpiStrip, riskRows, riskBreachChart, formatMagnitude, timeOptions } from './workspacePresentation.mjs';
import { preflightView, applyFix, createPreflightClient } from './preflightPresentation.mjs';
import { periodLabel, dailyRevenueSeries, channelSlices, chartQuestion } from './dashboardPresentation.mjs';
import { forecastChartData, forecastFreshness } from './forecastPresentation.mjs';
import { presentationChart } from './analystDashboardLayout.mjs';

const caps = JSON.parse(readFileSync(new URL('../../../analytics-api/tests/fixtures/capabilities_v31.json', import.meta.url), 'utf8'));
function component(relative, name) {
  const directory = mkdtempSync(join(tmpdir(), 'workspace-ui-'));
  try {
    const reactPath = dirname(createRequire(import.meta.url).resolve('react'));
    const compiled = buildSync({ entryPoints: [new URL(relative, import.meta.url).pathname], bundle: true, platform: 'node', format: 'cjs', write: false, alias: { react: reactPath }, external: [reactPath, `${reactPath}/*`] });
    const path = join(directory, 'component.cjs'); writeFileSync(path, compiled.outputFiles[0].contents);
    return createRequire(import.meta.url)(path)[name];
  } finally { rmSync(directory, { recursive: true, force: true }); }
}
const render = (Component, props) => renderToStaticMarkup(React.createElement(Component, props));

test('coverage bar text comes from the cached server snapshot', () => {
  const c = coverageSummary(caps);
  assert.equal(c.range, '01/01/2026 → 16/10/2026');
  assert.equal(c.freshness, 'Cập nhật theo đợt');
  assert.ok(c.lagging.some(l => l.includes('02/10/2026')));
  assert.equal(coverageSummary({ data_coverage: { status: 'loading' } }).status, 'loading');
  const html = render(component('../components/workspace/DataCoverageBar.tsx', 'DataCoverageBar'), { capabilities: caps });
  for (const text of ['Dữ liệu:', 'Cập nhật theo đợt', 'Đồng bộ gần nhất:']) assert.ok(html.includes(text), text);
  assert.ok(!html.includes('thời gian thực'));
});

test('seven product modes: six visible server missions + free form; hidden ones map to a visible mode', () => {
  const cards = missionCards(caps);
  assert.deepEqual(cards.map(c => c.label), ['Tổng quan', 'So sánh', 'Xếp hạng', 'Xu hướng', 'Dự báo', 'Rủi ro & cảnh báo']);
  assert.equal(visibleMissionId(caps, 'composition'), 'overview');
  assert.equal(visibleMissionId(caps, 'relationship'), null);
  assert.equal(visibleMissionId(caps, 'trend'), 'trend');
  const Picker = component('../components/workspace/MissionPicker.tsx', 'MissionPicker');
  const off = { ...caps, missions: caps.missions.map(m => m.id === 'forecast' ? { ...m, status: 'unavailable', reason: 'Không có dữ liệu' } : m) };
  const html = render(Picker, { capabilities: off, value: 'compare', onChange: () => {} });
  assert.equal((html.match(/data-mission=/g) || []).length, 6);
  assert.match(html, /data-mission="forecast"[^>]*disabled=""|disabled=""[^>]*data-mission="forecast"/);
  assert.ok(html.includes('Không có dữ liệu'));
});

test('template builder offers only compatible metrics and fills a Vietnamese question', () => {
  const forecastable = missionMetrics(caps, 'forecast').map(m => m.id);
  assert.deepEqual(forecastable.sort(), ['delivery_count', 'order_count', 'revenue', 'store_order_count', 'store_revenue']);
  const month = timeOptions(caps).find(t => t.id === '2026-09');
  assert.equal(buildQuestion(caps, 'compare', { metric: 'revenue', dimension: 'city', value_a: 'Hồ Chí Minh', value_b: 'Hà Nội', time: month.phrase }),
    'So sánh doanh thu theo tỉnh/thành trong dữ liệu giữa Hồ Chí Minh và Hà Nội tháng 9 năm 2026');
  assert.equal(buildQuestion(caps, 'forecast', { metric: 'revenue', horizon: 3, cadence: 'month' }), 'Dự báo doanh thu 3 tháng tới');
  assert.equal(buildQuestion(caps, 'trend', { metric: 'order_cancellation_rate', granularity: 'week' }), 'Tỷ lệ hủy đơn theo tuần');
  assert.equal(buildQuestion(caps, 'compare', { metric: 'revenue' }), '');  // missing required slots
  // V3.2: the mission builder renders only the mission's contract slots and
  // emits canonical IDs (guided contract), not text for the AI to rediscover.
  const Builder = component('../components/workspace/MissionInputBuilder.tsx', 'MissionInputBuilder');
  const html = render(Builder, { capabilities: caps, mission: 'forecast', onApply: () => {} });
  assert.ok(html.includes('Dùng cấu hình này')); assert.ok(html.includes('không cần AI diễn giải'));
  assert.ok(!html.includes('Tỷ lệ hủy đơn'));  // not forecastable → not offered
  assert.ok(html.includes('tối đa 6'));
  assert.ok(!html.includes('aria-label="Chiều phân tích"'));  // forecast has no grouping control
});

test('suggestion chips are real example questions, filtered by mission', () => {
  const all = suggestionChips(caps, null);
  assert.ok(all.length >= 4 && all.every(q => q.split(' ').length >= 3));
  assert.ok(!all.some(q => caps.domains.some(d => d.label === q)));
  assert.ok(suggestionChips(caps, 'forecast').every(q => /dự báo/i.test(q) || caps.metrics.some(m => m.forecastable && q.includes(m.label))));
});

test('"Hỏi được gì?" lists 16 groups with badges, dimensions, search and unsupported items', () => {
  const groups = capabilityGroups(caps);
  assert.equal(groups.length, 26);  // PLAN 20/10: 16 + 10 business-coverage domains
  const revenue = groups.flatMap(g => g.metrics).find(m => m.id === 'revenue');
  assert.deepEqual(revenue.badges, ['Có xu hướng', 'Dự báo được']);
  assert.deepEqual(groups.flatMap(g => g.metrics).find(m => m.id === 'paused_sale_positions').badges, ['Hiện tại', 'Tín hiệu rủi ro', 'Không cộng qua thời gian']);  // V3.2: risk-signal badge
  assert.ok(capabilityGroups(caps, 'hủy đơn').flatMap(g => g.metrics).some(m => m.id === 'order_cancellation_rate'));
  assert.ok(unsupportedItems(caps).some(u => u.id === 'profit_margin' && u.nearest.length));
  const Drawer = component('../components/workspace/CapabilityDrawer.tsx', 'CapabilityDrawer');
  assert.ok(render(Drawer, { capabilities: caps, onAsk: () => {} }).includes('Hỏi được gì?'));
});

test('preflight view: understood chips, blocking, warnings and quick fixes', () => {
  const result = { status: 'warning', can_submit: true, understood: { metrics: [{ label: 'Doanh thu', alternatives: [{}, {}] }], dimensions: [{ label: 'Chi nhánh' }], filters: [], time: { source: 'default' },
    forecast: { requested: true, horizon: 12, unit: 'month' } }, findings: [{ level: 'warn', code: 'forecast_horizon_exceeded', message: 'Tối đa 6 tháng', fixes: [{ kind: 'replace_question', label: 'Đổi thành 6 tháng', question: 'Dự báo doanh thu 6 tháng tới' }] }] };
  const v = preflightView(result);
  assert.equal(v.tone, 'amber'); assert.equal(v.blocked, false);
  assert.deepEqual(v.chips.map(c => c.label), ['Doanh thu', 'Theo chi nhánh', 'Dự báo 12 tháng']);
  assert.deepEqual(applyFix('x', result.findings[0].fixes[0]), { question: 'Dự báo doanh thu 6 tháng tới' });
  assert.deepEqual(applyFix('abcdef', { kind: 'truncate', max_chars: 3 }), { question: 'abc' });
  assert.deepEqual(applyFix('x', { kind: 'set_time', time: { mode: 'custom', start: 'a', end: 'b' } }), { time: { mode: 'custom', start: 'a', end: 'b' } });
  assert.equal(applyFix('x', { kind: 'advice' }), null);
  const blocked = preflightView({ ...result, status: 'blocked', can_submit: false, findings: [{ level: 'block', code: 'privacy_blocked', message: 'Không', fixes: [] }] });
  assert.equal(blocked.blocked, true); assert.equal(blocked.tone, 'red');
  const Panel = component('../components/workspace/QuestionPreflight.tsx', 'QuestionPreflight');
  const html = render(Panel, { result, onFix: () => {} });
  assert.ok(html.includes('Đã nhận diện:')); assert.ok(html.includes('Đổi thành 6 tháng')); assert.ok(html.includes('data-finding="forecast_horizon_exceeded"'));
  assert.match(render(Panel, { result: { ...result, can_submit: false, findings: [{ level: 'block', code: 'privacy_blocked', message: 'Bị chặn', fixes: [] }] }, onFix: () => {} }), /role="alert"/);
});

test('preflight client debounces, cancels stale requests and never applies old results', async () => {
  const timers = [], calls = [], results = [];
  const pending = [];
  const client = createPreflightClient({ debounceMs: 400, setTimer: (fn, ms) => { timers.push({ fn, ms }); return timers.length; }, clearTimer: id => { timers[id - 1].cancelled = true; },
    fetchImpl: (url, init) => { calls.push(JSON.parse(init.body).question); return new Promise(resolve => pending.push(resolve)); },
    onResult: (result) => results.push(result) });
  client.request({ question: 'doanh' }); client.request({ question: 'doanh thu' });
  assert.equal(timers[0].cancelled, true); assert.equal(timers[1].ms, 400);
  timers[1].fn();                                   // first network request (for "doanh thu")
  client.request({ question: 'doanh thu năm 2024' }); timers[2].fn();
  pending[0]({ ok: true, json: async () => ({ question: 'stale' }) });     // late, stale response
  pending[1]({ ok: true, json: async () => ({ question: 'fresh' }) });
  await new Promise(r => setTimeout(r, 0)); await new Promise(r => setTimeout(r, 0));
  assert.deepEqual(calls, ['doanh thu', 'doanh thu năm 2024']);
  assert.deepEqual(results.map(r => r?.question), ['fresh']);
});

test('scope panel recognizes scope from the question; depth explains what it adds; no context/expectation', () => {
  const Panel = component('../components/workspace/AnalysisScopePanel.tsx', 'AnalysisScopePanel');
  const props = { capabilities: caps, preflight: null, showTime: true, showDepth: true, time: 'auto', start: '', end: '', scope: { mode: 'auto', filters: [] }, depth: 'deep', onTime() {}, onStart() {}, onEnd() {}, onScope() {}, onDepth() {} };
  const html = render(Panel, props);
  assert.ok(html.includes('Theo câu hỏi')); assert.ok(html.includes('Tự nhận diện từ câu hỏi'));
  assert.ok(!html.includes('aria-label="Loại phạm vi"'));  // no default "Sản phẩm" picker until narrowing is requested
  for (const depth of caps.analysis_depths) assert.ok(html.includes(depth.label.replace('Phân tích toàn diện', 'Toàn diện')));
  assert.ok(html.includes('data-depth-description'));
  assert.equal((html.match(/data-analysis-input=/g) || []).length, 3);
  const detected = render(Panel, { ...props, preflight: { understood: { filters: [{ label: 'Thành phố', display: 'Hà Nội' }], dimensions: [{ label: 'Chi nhánh' }] } } });
  assert.ok(detected.includes('Thành phố: Hà Nội')); assert.ok(detected.includes('Theo chi nhánh'));
  for (const removed of ['Ngữ cảnh phân tích', 'Mong muốn phân tích']) assert.ok(!html.includes(removed));
  const Workspace = component('../components/workspace/AnalystWorkspace.tsx', 'AnalystWorkspace');
  const page = render(Workspace, { capabilities: caps, status: null, value: { prompt: '', time: 'auto', start: '', end: '', scope: { mode: 'auto', filters: [] }, depth: 'deep', mission: null }, disabled: false, onChange() {}, onSubmit() {} });
  for (const removed of ['Ngữ cảnh phân tích', 'Mong muốn phân tích']) assert.ok(!page.includes(removed));
  assert.ok(page.includes('data-coverage-bar')); assert.equal((page.match(/data-mission=/g) || []).length, 6);
});

test('comparison difference, mission tab order and KPI strip are deterministic', () => {
  assert.equal(groupDifference([{ label: 'Hồ Chí Minh', value: 1696 }, { label: 'Hà Nội', value: 1000 }], 'label', 'value', 'VND').text, 'Hồ Chí Minh cao hơn 69,6%');
  assert.equal(groupDifference([{ label: 'A', value: 12 }, { label: 'B', value: 9.5 }], 'label', 'value', '%').text, 'A cao hơn 2,5 điểm %');
  assert.equal(groupDifference([{ label: 'A', value: 1 }], 'label', 'value'), null);
  const tabs = missionTabs([{ id: 'all', charts: [] }, { id: 'trend', charts: [] }, { id: 'comparison', charts: [] }], { tab_order: ['comparison', 'all', 'trend'] }, { forecast: true });
  assert.deepEqual(tabs.map(t => t.id), ['comparison', 'all', 'trend', 'forecast']);
  assert.deepEqual(orderChartsByMission([{ id: 'a' }, { id: 'b' }], { chart_order: ['b', 'a'] }).map(c => c.id), ['b', 'a']);
  const cards = kpiStrip([{ label: 'Doanh thu', value: 777400000, unit: 'VND' }, { label: 'Biến động', value: -3.2, unit: '%', feature: 'change' }], { analysis_explanation: [{ period: { start: '2026-09-01', end: '2026-09-30' } }] });
  assert.equal(cards[0].value, '777.400.000 đ'); assert.equal(cards[0].context, '01/09/2026 → 30/09/2026');
  assert.equal(cards[1].direction, 'down'); assert.equal(formatMagnitude(777400000, 'VND'), '777,4 triệu đ');
});

test('risk table renders server traffic lights; no composite score', () => {
  const result = { signals: [{ id: 'late_shift_high', label: 'Tỷ lệ ca đi trễ cao', metric_label: 'Tỷ lệ ca đi trễ', unit: '%', value: 20, threshold: 15, operator_symbol: '>', status: 'red', status_label: 'Vượt ngưỡng', definition: 'DI_TRE / ca đã chấm công', breakdown: { groups_in_breach: 2, groups_total: 5, dimension_label: 'Chi nhánh', worst: [] } },
    { id: 'store_rating_low', label: 'Điểm thấp', metric_label: 'Điểm', unit: 'điểm', value: null, threshold: 3.5, operator_symbol: '<', status: 'no_data', status_label: 'Không có dữ liệu' }], counts: { red: 1 }, composite_score: null, threshold_policy: 'Ngưỡng là mặc định hệ thống' };
  const rows = riskRows(result);
  assert.deepEqual(rows.map(r => [r.tone, r.value, r.threshold]), [['red', '20%', '> 15%'], ['gray', '—', '< 3,5 điểm']]);
  assert.deepEqual(riskBreachChart(result), [{ label: 'Tỷ lệ ca đi trễ cao', value: 2 }]);
  const html = render(component('../components/workspace/RiskSignalTable.tsx', 'RiskSignalTable'), { result });
  assert.ok(html.includes('data-status="red"')); assert.ok(html.includes('Ngưỡng là mặc định hệ thống'));
  assert.ok(!/điểm rủi ro tổng|risk score/i.test(html));
});

test('forecast panel draws history, forecast and 80% band from server data only', () => {
  const forecast = { status: 'ok', metric_label: 'Doanh thu', metric_unit: 'VND', unit: 'month', horizon: 2, method: 'naive', history: { start: '2026-04-01', end: '2026-09-01', periods: 6 },
    history_points: [{ period: '2026-08-01', value: 10 }, { period: '2026-09-01', value: 12 }],
    forecast: [{ period: '2026-10-01', value: 12, lower_80: 9, upper_80: 15, kind: 'in_progress' }, { period: '2026-11-01', value: 12, lower_80: 8, upper_80: 16, kind: 'future' }], backtest: { mae: 1 } };
  assert.equal(forecastChartData(forecast).history.length, 2);
  assert.ok(forecastFreshness(forecast, { freshness: { stale: true } }).some(n => n.includes('trễ')));
  const html = render(component('../components/ForecastPanel.tsx', 'ForecastPanel'), { forecasts: [forecast] });
  for (const marker of ['data-history-line', 'data-forecast-line', 'data-forecast-band', 'Khoảng 80%', 'Chất lượng kiểm tra lùi']) assert.ok(html.includes(marker), marker);
});

test('P5: period-scoped KPI labels, order units, incomplete day and ask-AI bridge', () => {
  assert.equal(periodLabel('30days'), '30 ngày gần nhất');
  const series = dailyRevenueSeries([{ date: '2026-10-14', revenue: 100 }, { date: '2026-10-15', revenue: 300 }, { date: '2026-10-16', revenue: 5 }], '2026-10-16');
  assert.equal(series.partialLast, true); assert.equal(series.period.end, '2026-10-15'); assert.equal(series.average, 200);
  assert.ok(series.notes[0].includes('chưa kết thúc'));
  assert.ok(!JSON.stringify(series).includes('secondary'));  // no fabricated comparison series
  const gapped = dailyRevenueSeries([{ date: '2026-10-01', revenue: 100 }, { date: '2026-10-02', revenue: 90 }, { date: '2026-10-05', revenue: 1 }], '2026-10-16');
  assert.deepEqual(gapped.data.map(d => d.series_1), [100, 90, null, null, 1]);
  assert.deepEqual(gapped.gaps, [['2026-10-03', '2026-10-04']]);
  assert.ok(gapped.notes.some(n => n.includes('từ 2026-10-03 đến 2026-10-04')));
  assert.equal(channelSlices({ store_orders: 3, delivery_orders: 1 }).unit, 'đơn');
  assert.equal(chartQuestion(caps, { metric: 'order_cancellation_rate', dimension: 'store' }), 'Tỷ lệ hủy đơn theo chi nhánh');
  assert.equal(chartQuestion(caps, { metric: 'unknown_metric' }), null);
  const source = readFileSync(new URL('../views/AnalyticsView.tsx', import.meta.url), 'utf8');
  assert.ok(!source.includes('* 0.88')); assert.ok(source.includes('Hỏi trợ lý AI về biểu đồ này'));
  assert.ok(source.includes('valueSuffix=" đơn"')); assert.ok(!source.includes('Liên tục 100% không gián đoạn'));
  assert.ok(!readFileSync(new URL('../components/Header.tsx', import.meta.url), 'utf8').includes('Dữ liệu thời gian thực'));
});

